/**
 * What the apps show about a book.
 */
public struct BookInfo: Equatable, Hashable {
    /**
     * Stable id: the ZIM `Name` metadata (e.g. `wikipedia_cs_all`), else the file name
     * without extension. Same id for the maxi and mini edition of one wiki.
     */
    public var id: String
    /**
     * `Name` metadata (may be empty).
     */
    public var name: String
    public var title: String
    public var description: String
    /**
     * ISO 639-3 code(s) from the metadata, e.g. `ces`, `slk`, `eng`.
     */
    public var language: String
    public var creator: String
    public var publisher: String
    public var date: String
    public var articleCount: UInt64
    public var mediaCount: UInt64
    /**
     * Path of the main page (pass it to `get`), if the book has one.
     */
    public var mainPath: String?
    public var sizeBytes: UInt64
    public var hasIndex: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Stable id: the ZIM `Name` metadata (e.g. `wikipedia_cs_all`), else the file name
         * without extension. Same id for the maxi and mini edition of one wiki.
         */id: String, 
        /**
         * `Name` metadata (may be empty).
         */name: String, title: String, description: String, 
        /**
         * ISO 639-3 code(s) from the metadata, e.g. `ces`, `slk`, `eng`.
         */language: String, creator: String, publisher: String, date: String, articleCount: UInt64, mediaCount: UInt64, 
        /**
         * Path of the main page (pass it to `get`), if the book has one.
         */mainPath: String?, sizeBytes: UInt64, hasIndex: Bool) {
        self.id = id
        self.name = name
        self.title = title
        self.description = description
        self.language = language
        self.creator = creator
        self.publisher = publisher
        self.date = date
        self.articleCount = articleCount
        self.mediaCount = mediaCount
        self.mainPath = mainPath
        self.sizeBytes = sizeBytes
        self.hasIndex = hasIndex
    }

    

    
}

