/**
 * Errors returned by every fallible core call.
 *
 * Flat on purpose: Kotlin and Swift see the variant plus a readable message.
 */
public 
enum CoreError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * Reading the file failed (unplugged drive, bad fd, permission).
     */
    case Io(message: String)
    
    /**
     * The file is not a ZIM, is truncated or corrupt, or an index does not belong to the book.
     */
    case InvalidZim(message: String)
    
    /**
     * No entry with that path (or no such metadata / index hit).
     */
    case NotFound(message: String)
    
    /**
     * A valid but unsupported feature (zlib/bzip2 clusters, old index version).
     */
    case Unsupported(message: String)
    
    /**
     * The caller cancelled a long operation (`build_index`).
     */
    case Cancelled(message: String)
    

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension CoreError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreError: FfiConverterRustBuffer {
    typealias SwiftType = CoreError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Io(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .InvalidZim(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .NotFound(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .Unsupported(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .Cancelled(
            message: try FfiConverterString.read(from: &buf)
        )
        

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CoreError, into buf: inout [UInt8]) {
        switch value {

        

        
        case .Io(_ /* message is ignored*/):
            writeInt(&buf, Int32(1))
        case .InvalidZim(_ /* message is ignored*/):
            writeInt(&buf, Int32(2))
        case .NotFound(_ /* message is ignored*/):
            writeInt(&buf, Int32(3))
        case .Unsupported(_ /* message is ignored*/):
            writeInt(&buf, Int32(4))
        case .Cancelled(_ /* message is ignored*/):
            writeInt(&buf, Int32(5))

        
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCoreError_lift(_ buf: RustBuffer) throws -> CoreError {
    return try FfiConverterTypeCoreError.lift(buf)
}

